function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw traditional diet character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 - 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 + 15, H/2 + 40);
  ctx.stroke();

  // Draw traditional diet food
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/4 - 20, H/2 + 60, 40, 20);
  ctx.fillStyle = 'green';
  ctx.fillRect(W/4 - 30, H/2 + 80, 20, 20);
  ctx.fillStyle = 'red';
  ctx.fillRect(W/4 + 10, H/2 + 80, 20, 20);

  // Draw modern disease character
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 - 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 + 15, H/2 + 40);
  ctx.stroke();

  // Draw modern disease food
  ctx.fillStyle = 'white';
  ctx.fillRect(W - W/4 - 20, H/2 + 60, 40, 20);
  ctx.fillStyle = 'grey';
  ctx.fillRect(W - W/4 - 30, H/2 + 80, 20, 20);
  ctx.fillStyle = 'blue';
  ctx.fillRect(W - W/4 + 10, H/2 + 80, 20, 20);

  // Animate characters and food
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50 + 10 * Math.sin(t));
  ctx.lineTo(W/4, H/2 + 50 + 10 * Math.sin(t) + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50 + 10 * Math.cos(t));
  ctx.lineTo(W - W/4, H/2 + 50 + 10 * Math.cos(t) + 20);
  ctx.stroke();
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/4 - 20 + 5 * Math.sin(t), H/2 + 60, 40, 20);
  ctx.fillStyle = 'white';
  ctx.fillRect(W - W/4 - 20 + 5 * Math.cos(t), H/2 + 60, 40, 20);

  ctx.restore();
}
